function C.Apply(q)
 if not q then return end
 local links=C.links[q.id]
 if links then q.dungeons=ns.QuestieAdapter.Copy(links);q.dungeon=q.dungeon or links[1];q.dungeonReviewed='2026-10-06' end
 for key,value in pairs(C.fixes[q.id] or {})do q[key]=ns.QuestieAdapter.Copy(value)end
 return q
end
for id,q in pairs(C.new)do ns.QuestDB[id]=C.Apply(q)end
for id in pairs(C.links)do if ns.QuestDB[id]then C.Apply(ns.QuestDB[id])end end
for key,items in pairs(C.loot)do
 local d=ns.DungeonDB[key]
 if d then d.bossLoot={};d.lootItems=items;for _,item in ipairs(items)do if item.dropSourceConfirmed then d.bossLoot[#d.bossLoot+1]=item.id end end end
end
